ROWS = {
# ---- OSI: [하는 일, 택배로 치면, 대표 단어]
"n-osi7": ["사람이 직접 쓰는 <b>프로그램과 서비스</b>가 동작하는 층. 웹 보기, 메일, 파일 전송.", "택배 앱에서 \"보내기\" 누르기", "HTTP, FTP, SMTP, DNS, Telnet"],
"n-osi6": ["데이터를 <b>상대가 알아볼 수 있는 형식</b>으로 바꾼다. 암호화, 압축, 문자 인코딩.", "물건을 규격 상자에 맞게 포장하기", "JPEG, MPEG, ASCII, 암호화·압축"],
"n-osi5": ["두 컴퓨터 사이의 <b>대화(연결)를 시작하고 유지하고 끝낸다</b>. 중간 저장점(동기점)을 둔다.", "배송 시작부터 끝까지 일정 관리", "세션 연결·종료, 동기점(체크포인트)"],
"n-osi4": ["보낸 데이터가 <b>빠짐없이 순서대로</b> 도착하게 한다. 잘못되면 다시 보낸다(오류 제어), 너무 빠르면 속도를 맞춘다(흐름 제어).", "분실되면 다시 보내고, 받는 쪽이 받을 수 있는 만큼만 보내기", "TCP, UDP / 단위: <b>세그먼트</b>"],
"n-osi3": ["<b>IP 주소</b>를 보고 목적지까지 <b>가장 좋은 길</b>을 찾는다(라우팅).", "주소 보고 어느 물류센터를 거쳐 갈지 정하기", "IP, ICMP, ARP, <b>라우터</b> / 단위: <b>패킷</b>"],
"n-osi2": ["바로 옆 장비까지 <b>MAC 주소</b>로 전달하고, 전송 중 오류를 검사한다.", "동네 집배원이 옆 건물까지 배달", "이더넷, <b>스위치</b>, 브리지 / 단위: <b>프레임</b>"],
"n-osi1": ["0과 1을 <b>전기 신호·빛·전파</b>로 바꿔 실제로 선을 타고 보낸다.", "도로와 트럭 그 자체", "케이블, <b>허브, 리피터</b> / 단위: <b>비트</b>"],
# ---- 용어: [뜻, 외우는 법]
"n-tcp": ["보내기 전에 <b>연결을 맺고</b>, 데이터가 <b>빠짐없이 순서대로</b> 도착했는지 확인하는 전송 방식. 못 받은 건 다시 보낸다.", "등기 우편. 도착 확인까지 받아서 느리지만 확실함. 웹, 이메일, 파일 전송에 사용"],
"n-udp": ["연결 없이 <b>그냥 바로 보내는</b> 방식. 도착 확인을 안 해서 빠르지만 중간에 빠져도 모른다.", "전단지 뿌리기. 조금 빠져도 괜찮고 빠른 게 중요한 곳: 영상 스트리밍, 게임, DNS"],
"n-3way": ["TCP가 연결을 맺는 3단계: ① <b>SYN</b>(연결하자) → ② <b>SYN+ACK</b>(좋아, 너도 들려?) → ③ <b>ACK</b>(응, 들려).", "전화: \"여보세요?\" → \"네, 들려요. 제 말도 들려요?\" → \"네, 들려요.\" 이후 대화 시작"],
"n-ip": ["IPv4 = <mark>32비트</mark>, 8비트씩 4덩어리를 점으로 구분 (192.168.0.1). IPv6 = <mark>128비트</mark>, 16비트씩 8덩어리를 콜론으로 구분 (2001:db8::1).", "IPv4 주소가 부족해서 IPv6가 나옴. IPv6에는 <b>브로드캐스트가 없고</b> 유니캐스트(1:1)·멀티캐스트(1:그룹)·애니캐스트(1:가장 가까운 하나)가 있음"],
"n-arp": ["<b>ARP</b>: IP 주소를 알 때 그 컴퓨터의 <b>MAC 주소(랜카드 고유 번호)</b>를 알아낸다. <b>RARP</b>: 반대로 MAC 주소로 IP 주소를 알아낸다.", "R = Reverse(거꾸로). ARP = 이름(IP)으로 얼굴(MAC) 찾기"],
"n-icmp": ["네트워크에서 <b>오류가 났거나 상태를 알려줄 때</b> 쓰는 메시지 프로토콜. \"목적지에 도달할 수 없음\" 같은 알림.", "<code>ping</code> 명령어가 ICMP를 씀. Smurf, Ping of Death 공격에도 등장"],
"n-dns": ["사람이 외우기 쉬운 <b>도메인 이름</b>(naver.com)을 컴퓨터가 쓰는 <b>IP 주소</b>로 바꿔 준다.", "전화번호부. 이름을 찾으면 번호가 나옴. 포트 53"],
"n-dhcp": ["네트워크에 접속한 기기에 <b>IP 주소를 자동으로 빌려 준다</b>.", "카페 와이파이에 붙으면 IP를 직접 안 넣어도 인터넷이 되는 이유"],
"n-nat": ["내부에서 쓰는 <b>사설 IP</b>를 인터넷에 나갈 때 <b>공인 IP</b>로 바꿔 준다. 공인 IP 하나로 여러 기기가 인터넷을 쓴다.", "회사 대표번호 하나로 여러 내선 전화를 쓰는 것. 집 공유기가 하는 일"],
"n-rip": ["<b>RIP</b>: 거리(거쳐 가는 라우터 수, 홉)로 길을 고름. <mark>최대 15홉</mark>, 소규모용. <b>OSPF</b>: 네트워크 전체 지도(링크 상태)를 보고 고름, 대규모용. <b>BGP</b>: 서로 다른 조직 네트워크(AS)끼리 길을 주고받음.", "RIP = 정거장 수만 셈, OSPF = 지도 앱처럼 전체 상황 보고 판단, BGP = 나라끼리 국경 도로 협의"],
"n-dev": ["<b>1계층</b>: 허브, 리피터 (신호만 키우거나 뿌림). <b>2계층</b>: 스위치, 브리지 (MAC 주소 보고 전달). <b>3계층</b>: 라우터 (IP 주소 보고 길 찾기).", "장비가 똑똑할수록 층이 높다. 허브는 무조건 다 뿌림 → 스위치는 받을 사람한테만 → 라우터는 다른 네트워크까지 길 찾기"],
# ---- 포트: [포트, 하는 일]
"n-p-ftp": ["<b>20</b>(데이터 전송), <b>21</b>(제어·명령)", "파일 전송. 두 개를 씀: 명령은 21, 실제 파일은 20"],
"n-p-ssh": ["<b>22</b> / <b>23</b>", "원격 접속. SSH는 <b>암호화</b>해서 안전, Telnet은 암호화 없이 그대로(평문) 보내서 위험. 22가 더 안전한 쪽"],
"n-p-smtp": ["<b>25</b> / <b>110</b> / <b>143</b>", "SMTP = 메일 <b>보내기</b>. POP3 = 메일을 내 PC로 <b>가져오기</b>(서버에서 지워짐). IMAP = 서버에 <b>두고 보기</b>(폰·PC 동기화)"],
"n-p-dns": ["<b>53</b>", "도메인 이름을 IP로 바꿔 줌"],
"n-p-http": ["<b>80</b> / <b>443</b>", "웹사이트. HTTPS는 HTTP에 암호화(TLS)를 더한 것. 주소창 자물쇠 = 443"],

# ---- 보안: [뜻, 외우는 법]
"x-dos": ["서버에 요청을 한꺼번에 엄청 보내서 <b>진짜 사용자가 못 쓰게</b> 만드는 공격. DDoS는 해커가 감염시킨 수많은 PC(좀비 PC, 봇넷)로 <b>동시에</b> 공격한다.", "가게 앞에 가짜 손님 수천 명을 줄 세워 진짜 손님이 못 들어오게 함. 보안 3요소 중 <b>가용성</b>을 깨는 공격"],
"x-syn": ["TCP 연결 3단계 중 <b>SYN만 계속 보내고 마지막 ACK를 안 보낸다</b>. 서버는 답을 기다리며 연결 자리를 잡아 두다가 자리가 꽉 차서 진짜 연결을 못 받는다.", "전화를 걸어 \"여보세요?\"만 하고 대답 없이 끊기를 수천 번. 키워드: <b>SYN, 3-way handshake, 반쯤 열린 연결</b>"],
"x-smurf": ["보내는 사람 주소를 <b>피해자 IP로 속이고</b>, ICMP(ping)를 네트워크 전체(<b>브로드캐스트</b>)에 보낸다. 그러면 모든 컴퓨터가 피해자에게 한꺼번에 답장을 보낸다.", "내 이름으로 전교생에게 \"답장 주세요\" 쪽지를 돌려서 답장 폭탄 맞게 하기. 키워드: <b>ICMP + 브로드캐스트 + IP 위조</b>"],
"x-pod": ["ping(ICMP) 패킷을 허용된 최대 크기(<b>65,535바이트</b>)보다 <b>크게</b> 만들어 보낸다. 받는 쪽이 처리하다 멈추거나 다운된다.", "이름 그대로 \"죽음의 핑\". 너무 큰 핑 하나로 쓰러뜨림"],
"x-land": ["패킷의 <b>보내는 IP와 받는 IP를 똑같이</b>(피해자 IP로) 만들어 보낸다. 피해자는 자기 자신에게 계속 응답하다 멈춘다.", "Land = 자기 땅. 자기가 자기한테 편지 보내고 답장하는 무한 반복. 키워드: <b>출발지 = 목적지</b>"],
"x-tear": ["큰 데이터는 조각(Fragment)으로 나눠 보내고 받는 쪽이 순서 번호(<b>Offset</b>)로 다시 맞춘다. 이 번호를 <b>일부러 겹치거나 틀리게</b> 만들어 조립하다 오류가 나게 한다.", "번호가 뒤죽박죽인 퍼즐 조각을 보내기. 눈물방울처럼 조각조각. 키워드: <b>Fragment Offset</b>"],
"x-sqli": ["로그인 칸, 검색창 같은 <b>입력칸에 SQL 문을 몰래 넣어서</b> DB를 마음대로 조회·수정한다.", "아이디 칸에 <code>' OR 1=1 --</code>를 넣으면 조건이 항상 참이 되어 비밀번호 없이 로그인. 막는 법: 입력값 검증, Prepared Statement"],
"x-xss": ["게시판 글 등에 <b>악성 스크립트(JavaScript)를 심어 두면</b>, 그 글을 연 다른 사람 <b>브라우저에서 실행</b>되어 쿠키·정보를 빼 간다.", "Cross-Site Scripting. 게시글에 <code>&lt;script&gt;</code>를 넣는 것. 막는 법: 입력값의 <code>&lt;</code> <code>&gt;</code>를 이스케이프"],
"x-csrf": ["로그인한 사용자가 악성 링크를 누르면, <b>그 사람 권한으로</b> 원치 않는 요청(송금, 비밀번호 변경)이 서버로 날아간다.", "Forgery = 위조. XSS는 <b>사용자 브라우저</b>에서 스크립트가 도는 것, CSRF는 사용자 몰래 <b>서버에 요청</b>을 보내는 것. 막는 법: CSRF 토큰"],
"x-phish": ["<b>피싱</b>: 은행·기관인 척 가짜 메일·사이트로 개인정보를 빼 감. <b>스미싱</b>: 문자(SMS)로 하는 피싱. <b>스피어 피싱</b>: 특정 한 사람을 조사해서 맞춤으로 속임.", "피싱 = Private data + Fishing(낚시). 스미싱 = SMS + 피싱. 스피어 = 작살로 한 마리만 노림"],
"x-pharm": ["DNS나 PC의 hosts 파일을 조작해서, 사용자가 <b>주소를 정확히 입력해도</b> 가짜 사이트로 보낸다.", "피싱은 가짜 링크를 누르게 속이는 것, 파밍은 <b>진짜 주소를 쳐도</b> 가짜로 감. 한 단계 더 교묘함"],
"x-sniff": ["네트워크에 흐르는 데이터를 <b>몰래 엿보거나 엿듣는</b> 공격. 데이터를 바꾸지는 않는다.", "sniff = 킁킁 냄새 맡기. 도청. 막는 법: 암호화"],
"x-spoof": ["IP 주소, MAC 주소, DNS 등을 <b>위조해서 다른 사람인 척</b> 속이는 공격. 예) ARP 스푸핑: 내 MAC을 게이트웨이 것처럼 속여 남의 데이터를 나한테 오게 함.", "spoof = 속이다, 사칭. 스니핑은 엿듣기만, 스푸핑은 <b>신분을 위장</b>"],
"x-hijack": ["이미 로그인되어 열려 있는 <b>세션(연결)을 가로채서</b> 그 사용자인 척한다. 비밀번호 없이도 들어갈 수 있다.", "hijack = 납치. 운전 중인 차를 뺏는 것. 세션 ID를 훔치는 게 핵심"],
"x-social": ["기술 대신 <b>사람의 심리를 속여서</b> 비밀번호나 정보를 얻는 방법.", "\"IT팀인데요, 점검 때문에 비밀번호 좀 알려 주세요\" 전화. 어깨 너머로 비밀번호 훔쳐보기"],
"x-apt": ["특정 조직을 목표로 정하고 <b>오랫동안 몰래, 끈질기게</b> 여러 방법을 써서 공격한다.", "Advanced Persistent Threat. Persistent = 끈질긴. 몇 달씩 숨어서 정보를 빼 감"],
"x-zero": ["취약점이 알려진 뒤 <b>보안 패치가 나오기 전</b>에 그 틈을 노리는 공격.", "막을 방법이 나오기까지 대응할 시간이 0일(Zero-day)"],
"x-water": ["공격 대상이 <b>자주 방문하는 웹사이트</b>를 먼저 감염시켜 놓고, 대상이 들어오기를 기다린다.", "사자가 동물들이 물 마시러 오는 물웅덩이(Watering Hole)에서 기다리는 것"],
"x-virus": ["다른 정상 파일에 <b>붙어서(숙주 필요)</b> 그 파일이 실행될 때 퍼진다. 혼자서는 못 퍼진다.", "감기 바이러스처럼 숙주가 있어야 함. 웜과 구별이 자주 나옴"],
"x-worm": ["다른 파일 없이 <mark>혼자서</mark> 자기를 복제해 네트워크를 타고 퍼진다.", "벌레(worm)가 스스로 기어다님. 숙주가 필요 없다는 게 바이러스와 차이"],
"x-trojan": ["게임, 유틸리티 같은 <b>정상 프로그램인 척</b> 숨어 있다가 몰래 나쁜 짓을 한다. <mark>스스로 복제해 퍼지지는 않는다</mark>.", "트로이 전쟁의 목마: 선물(목마) 안에 병사가 숨어 있음"],
"x-ransom": ["파일을 <b>암호화해서 못 열게</b> 만들고, 풀어 주는 대가로 돈(주로 암호화폐)을 요구한다.", "ransom = 몸값. 파일을 인질로 잡는 것"],
"x-root": ["<b>루트킷</b>: 관리자(root) 권한을 얻고 자기 흔적을 숨기는 도구 모음. <b>백도어</b>: 정상 인증을 거치지 않고 몰래 들어오는 뒷문. <b>키로거</b>: 키보드로 친 내용을 몰래 기록.", "root = 관리자, back door = 뒷문, key + logger(기록기)"],
"x-sym": ["암호화할 때와 풀 때 <b>같은 키 하나</b>를 쓴다. 빠르지만 키를 안전하게 나눠 주기가 어렵다. 종류: <mark>DES, AES, SEED, ARIA</mark>.", "집 열쇠 하나를 복사해 나눠 갖기. SEED와 ARIA는 한국에서 만든 것"],
"x-asym": ["<b>공개키</b>(누구나 가짐)로 잠그고 <b>개인키</b>(나만 가짐)로 연다. 키 나눠 주기 문제가 없지만 느리다. 종류: <mark>RSA, ECC, ElGamal</mark>.", "우체통: 편지는 누구나 넣을 수 있지만(공개키) 꺼내는 건 열쇠 가진 주인만(개인키)"],
"x-keys": ["n명이 서로 암호 통신할 때 필요한 키 개수. 대칭키 = <mark>n(n−1)/2</mark> (두 명마다 하나씩), 비대칭키 = <mark>2n</mark> (한 명당 공개키·개인키 2개).", "10명이면 대칭키 10×9/2 = 45개, 비대칭키 10×2 = 20개"],
"x-hash": ["어떤 데이터든 <b>정해진 길이의 값</b>으로 바꾼다. 거꾸로 원래 값을 알아낼 수 없다. 데이터가 바뀌었는지(무결성) 확인할 때 쓴다. 종류: MD5, SHA.", "사람의 지문. 지문으로 사람을 되살릴 순 없지만 같은 사람인지는 알 수 있음. 비밀번호도 해시로 저장"],
"x-mac": ["<b>MAC</b>(강제적): 관리자가 정한 <b>보안 등급</b>으로 접근을 강제로 통제. <b>DAC</b>(임의적): 데이터 <b>주인</b>이 누구에게 줄지 마음대로 정함. <b>RBAC</b>(역할 기반): <b>직급·역할</b>에 따라 권한을 줌.", "MAC = 군대 비밀 등급(Mandatory 강제). DAC = 내 구글 드라이브 공유 설정(Discretionary 재량). RBAC = 팀장이면 결재 권한(Role)"],
"x-ids": ["<b>방화벽</b>: 정해 둔 규칙대로 통과·차단. <b>IDS</b>: 침입을 <mark>탐지</mark>하고 알리기만 함. <b>IPS</b>: 침입을 탐지해서 <mark>차단</mark>까지 함.", "IDS = Detection = CCTV(보고 알림만), IPS = Prevention = 경비원(보고 막음)"],
"x-honey": ["일부러 <b>허술해 보이는 가짜 시스템</b>을 만들어 공격자를 끌어들이고, 공격 방법을 관찰·기록한다.", "꿀단지(Honey pot)로 벌레를 모으는 함정"],
"x-vpn": ["<b>VPN</b>: 인터넷 같은 공용망 위에 <b>암호화된 나만의 통로</b>를 만들어 사설망처럼 쓴다. <b>SSO</b>: <b>한 번 로그인</b>으로 여러 서비스를 이어서 쓴다.", "VPN = 공용 도로 위의 전용 터널. SSO = Single Sign-On, 구글 로그인 한 번으로 유튜브·지메일 다 쓰기"],
"x-proto": ["<b>SSL/TLS</b>: 웹 브라우저와 서버 사이 통신을 암호화 (HTTPS). <b>IPSec</b>: IP 계층(3계층)에서 암호화. AH(인증·무결성)와 ESP(암호화까지)로 구성.", "IPSec 모드 두 가지: 전송 모드(데이터만 보호), 터널 모드(패킷 전체를 보호, VPN에 사용)"],
"x-auth": ["본인 확인 방법 4가지: <b>지식</b>(아는 것: 비밀번호, PIN), <b>소유</b>(가진 것: OTP, 스마트카드), <b>존재</b>(나 자체: 지문, 홍채, 얼굴), <b>행위</b>(내 행동: 서명, 걸음걸이, 목소리).", "두 가지 이상을 섞으면 다중 인증(MFA). 예) 비밀번호(지식) + 문자 인증번호(소유)"],

# ---- UML 표: [뜻, 외우는 법]
"u-vis": ["클래스 속성·메서드 앞에 붙이는 접근 범위: <b>+</b> public(누구나), <b>−</b> private(나만), <b>#</b> protected(나와 자식 클래스), <b>~</b> package(같은 패키지만).", "+ 는 열려 있음, − 는 빼서 숨김, # 은 울타리 쳐서 가족(자식)만, ~ 는 동네(패키지)만"],
"u-inc": ["유스케이스 사이 관계. <b>&lt;&lt;include&gt;&gt;</b>: 실행하면 <b>반드시 같이</b> 실행되는 기능(필수). <b>&lt;&lt;extend&gt;&gt;</b>: <b>조건에 따라 가끔</b> 추가되는 기능(선택).", "\"결제하기\"는 항상 \"로그인\"을 포함(include). \"결제하기\"에 \"쿠폰 적용\"은 원할 때만(extend). include = 포함, extend = 확장(덤)"],
"u-parts": ["UML을 이루는 3가지: <b>사물</b>(Things, 클래스·객체 같은 대상), <b>관계</b>(Relationships, 대상끼리 연결), <b>다이어그램</b>(Diagram, 이것들을 그린 그림).", "\"무엇이(사물), 어떻게 연결돼서(관계), 그림으로(다이어그램)\""],
"u-actor": ["시스템 <b>바깥</b>에서 시스템을 사용하는 사람이나 다른 시스템. 유스케이스 다이어그램에 졸라맨 모양으로 그린다.", "쇼핑몰 시스템에서 고객, 관리자, 외부 결제 시스템이 액터. 시스템 안에 있는 건 액터가 아님"],
}

# UML 카드 (.ans 안쪽 HTML)
CARDS = {
"u-struct": """<p class="why">시스템이 <b>무엇으로 이루어져 있는지</b>를 보여 주는 그림. 시간이 흘러도 안 변하는 모습 = 사진.</p>
<ol class="steps">
<li><b>클래스</b>: 클래스들과 그 속성·메서드, 서로의 관계. 프로그램의 설계도. <mark>가장 많이 나옴</mark></li>
<li><b>객체</b>: 클래스로 실제 만든 객체들이 <b>어느 한 순간</b>에 어떤 값을 갖고 연결돼 있는지. 설계도로 지은 집의 사진</li>
<li><b>컴포넌트</b>: 프로그램을 이루는 <b>부품(모듈)</b>과 그 연결</li>
<li><b>배치</b>: 서버, PC 같은 <b>물리적 장비</b>에 무엇이 설치되는지. 서버실 배치도</li>
<li><b>복합체 구조</b>: 클래스 <b>내부</b>가 어떻게 생겼는지</li>
<li><b>패키지</b>: 관련 요소를 <b>폴더처럼 묶은</b> 것과 그 관계</li>
</ol>
<p class="why"><b>외우는 법</b>: "클래스 객체가 컴퓨터에 배치돼서 복잡해서 패스"</p>""",

"u-behav": """<p class="why">시스템이 <b>어떻게 움직이는지</b>를 보여 주는 그림. 시간에 따라 일어나는 일 = 동영상.</p>
<ol class="steps">
<li><b>유스케이스</b>: 사용자(액터)가 시스템으로 <b>할 수 있는 기능</b> 목록. 식당 메뉴판</li>
<li><b>시퀀스</b>: 객체끼리 <mark>시간 순서대로</mark> 메시지를 주고받는 모습. 위에서 아래로 시간이 흐름. 카톡 대화창</li>
<li><b>커뮤니케이션</b>: 시퀀스와 같은 내용을 객체 간 <b>연결 관계</b> 중심으로 그림</li>
<li><b>상태</b>: 객체 하나의 <b>상태가 어떻게 바뀌는지</b>. 주문: 접수 → 결제완료 → 배송중 → 완료. 신호등</li>
<li><b>활동</b>: 일이 처리되는 <b>흐름과 조건 분기</b>. 순서도(flowchart)</li>
<li><b>타이밍</b>: 시간에 따라 상태가 <b>언제</b> 바뀌는지 시간축으로</li>
<li><b>상호작용 개요</b>: 여러 상호작용 다이어그램을 묶어 <b>큰 흐름</b>으로</li>
</ol>
<p class="why"><b>외우는 법</b>: "유시커 상활 타상". 문제에 \"시간 순서, 메시지\"가 보이면 시퀀스, \"상태 변화\"면 상태, \"흐름, 분기\"면 활동.</p>""",
}

# UML 관계 카드는 <p class="ex ans"> 안쪽만 바꿈
REL = {
"u-assoc": "두 클래스가 <b>서로 알고 연결</b>돼 있는 가장 기본 관계. 실선으로 잇는다(방향이 있으면 화살표). 예) 학생 — 강의: 학생은 강의를 수강한다",
"u-dep": "한 클래스가 다른 클래스를 <b>잠깐 빌려 쓰는</b> 약한 관계. 메서드 매개변수나 지역변수로만 쓰고 끝남. 점선 + 열린 화살표. 예) 주문.결제하기(카드) → 카드를 잠깐 씀",
"u-gen": "<mark>상속</mark>(is-a). 자식이 부모의 특징을 물려받음. 실선 + <b>빈 삼각형</b>이 <b>부모 쪽</b>을 가리킴. 예) 강아지 ▷ 동물: 강아지는 동물이다. Java의 extends",
"u-real": "<b>인터페이스를 구현</b>하는 관계. 약속(인터페이스)을 실제로 만든 것. <mark>점선</mark> + 빈 삼각형. 예) 카드결제 ⇢▷ 결제가능. Java의 implements. 일반화와 삼각형은 같고 <b>선만 점선</b>",
"u-agg": "전체와 부분 관계인데, 부분이 <mark>따로 살 수 있음</mark>. <b>빈 마름모</b>가 <b>전체 쪽</b>에 붙음. 예) 컴퓨터 ◇— 마우스: 컴퓨터를 버려도 마우스는 다른 컴퓨터에 씀",
"u-comp": "전체와 부분 관계인데, 전체가 없어지면 <mark>부분도 같이 없어짐</mark>. <b>채운 마름모</b>가 전체 쪽. 예) 집 ◆— 방: 집을 허물면 방도 사라짐. 집합보다 강한 관계",
}
